-- PoE2 Craft Overlay : Craft/Prices.lua
-- Currency prices from Craft of Exile's published data (Data/prices.lua, generated by
-- tools/fetch_prices.py).
--
-- A price only means something together with its league and age, so this module never
-- hands out a bare number: callers ask whether the snapshot applies (matchesLeague) and
-- get the league, fetch time and source alongside the value. The panel therefore stays
-- silent unless the snapshot really covers the league being played, while the MCP tools
-- report it with the label so an AI client can weigh it.

local Prices = { }

local cached = nil

local function snapshot()
	if cached == nil then
		local ok, loaded = pcall(require, "Data.prices")
		cached = (ok and type(loaded) == "table") and loaded or false
	end
	return cached or nil
end

--- Snapshot metadata: league, fetch time, source, unit. Never nil.
function Prices.info()
	local data = snapshot()
	if not data then
		return {
			available = false,
			reason = "no price snapshot: run tools/fetch_prices.py",
		}
	end
	return {
		available = true,
		league = data.league,
		fetchedAt = data.fetchedAt,
		source = data.source,
		url = data.url,
		unit = data.unit,
		currencies = data.currencyCount,
	}
end

--- Price of a currency in the snapshot's unit, or nil when unknown.
function Prices.unitPrice(currencyName)
	local data = snapshot()
	if not data or not currencyName then
		return nil
	end
	return (data.currency or { })[tostring(currencyName)]
end

--- The currency rates the page shows.
--
-- All three are derived from the same snapshot (which is quoted in chaos), so a rate can
-- never contradict the crafting costs computed from it:
--   divine in chaos, divine in exalted, chaos in exalted.
function Prices.rates()
	local divine = Prices.unitPrice("Divine Orb")
	local exalted = Prices.unitPrice("Exalted Orb")
	local chaos = Prices.unitPrice("Chaos Orb") or 1
	local rates = { }
	if divine and chaos and chaos > 0 then
		rates.divineChaos = divine / chaos
	end
	if divine and exalted and exalted > 0 then
		rates.divineExalted = divine / exalted
	end
	if exalted and exalted > 0 then
		rates.chaosExalted = chaos / exalted
	end
	return rates
end

--- Local icon per currency name (Data/currency_icons.lua), or an empty table.
function Prices.icons()
	local ok, data = pcall(require, "Data.currency_icons")
	if not ok or type(data) ~= "table" or type(data.icons) ~= "table" then
		return { }
	end
	return data.icons
end

--- Does the snapshot cover the league the overlay is configured for?
-- A snapshot the player picked explicitly (tools/fetch_prices.py --league) counts as
-- theirs: they answered "which league am I playing", so it is used as is.
-- @param leagueName league name from the ruleset (e.g. "0.5.5 Forbidden Rites")
-- @param override config.ui.pricesLeague: true accepts any league, a string matches it
function Prices.matchesLeague(leagueName, override)
	local data = snapshot()
	if not data then
		return false, "no snapshot"
	end
	if data.chosen == true and override == nil then
		return true, nil
	end
	if override == true then
		return true, nil
	end
	local wanted = type(override) == "string" and override or leagueName
	if not wanted or wanted == "" then
		return false, "no league configured"
	end
	local snapshotLeague = tostring(data.league or "")
	local wantedText = tostring(wanted)
	if snapshotLeague == "" then
		return false, "snapshot has no league"
	end
	-- Tolerate "Forbidden Rites" matching "0.5.5 Forbidden Rites".
	if wantedText:find(snapshotLeague, 1, true) or snapshotLeague:find(wantedText, 1, true) then
		return true, nil
	end
	return false, string.format("snapshot is for %q, this league is %q", snapshotLeague, wantedText)
end

--- Cost of one step in the snapshot's unit, or nil when it cannot be priced.
-- @param currencyName display name of the currency (e.g. "Greater Exalted Orb")
-- @param amount how many of it the step uses
function Prices.stepCost(currencyName, amount)
	local unit = Prices.unitPrice(currencyName)
	if not unit then
		return nil
	end
	return unit * (amount or 1)
end

--- How old the snapshot is, in hours, or nil when the stamp cannot be read.
-- The stamp is written as "YYYY-MM-DD HH:MM" by the fetcher.
function Prices.ageHours(fetchedAt)
	local text = tostring(fetchedAt or "")
	local year, month, day, hour, minute = text:match("^(%d%d%d%d)-(%d%d)-(%d%d) (%d%d):(%d%d)$")
	if not year then
		return nil
	end
	local when = os.time({
		year = tonumber(year), month = tonumber(month), day = tonumber(day),
		hour = tonumber(hour), min = tonumber(minute), sec = 0,
	})
	if not when then
		return nil
	end
	return (os.time() - when) / 3600
end

--- Is the snapshot older than the limit? A day-old rate quoted as today's is worse than none,
-- and without the agent nothing refreshes the file, so the panel has to say when it is stale.
function Prices.isStale(fetchedAt, limitHours)
	local age = Prices.ageHours(fetchedAt)
	if not age then
		return false
	end
	return age > (tonumber(limitHours) or 24)
end

return Prices
